import{z as s,x as l,o as n,c as d,q as t,j as A,D as E,d as r,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"2008 与影子银行","description":"","frontmatter":{"title":"2008 与影子银行","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gfc-shadow-banking.md","filePath":"econ/gfc-shadow-banking.md","lastUpdated":1791063341000}'),p={name:"econ/gfc-shadow-banking.md"};function h(D,a,c,m,C,P){const o=l("Mermaid");return n(),d("div",null,[a[2]||(a[2]=t('<h1 id="_2008-与影子银行" tabindex="-1">2008 与影子银行 <a class="header-anchor" href="#_2008-与影子银行" aria-label="Permalink to &quot;2008 与影子银行&quot;">​</a></h1><div class="epigraph"><p>批发融资链条把安全资产做成可挤兑的短债：回购与资产支持商业票据没有存款保险，抵押品价格一跌，展期停止。中心国家也可以突然停止，不必原罪。</p><footer>—— Gorton, Slapped by the Invisible Hand, 2010；Pozsar 影子银行图；Bernanke 对大萧条与 2008 的对照；Adrian and Shin 杠杆周期</footer></div><p><a href="/econ/east-asian-crisis">上一课</a>的挤兑发生在新兴市场的美元短债上。本课缺口是 2007–09 的中心国家：住房按揭被做成证券，放进表外管道，靠隔夜回购与 ABCP 融资。没有金本位，没有钉住泰铢，却有同类的期限错配。Bernanke 带着大萧条课的银行加速器进场，但对象从存款挤兑换成回购挤兑。后课欧债把银行与主权再锁回回路；本课先钉影子银行。不写限价簿，不写回测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统银行：短存款、长贷款，有准备金、保险与最后贷款人。影子链：货币市场基金与证券交易商用可调保证金的回购持有证券化按揭，管道用 ABCP 持有同样资产。看起来「安全」，因为优先档与超额抵押；房价与相关证券价格一跌，折扣率上升，等于提高准备金率，杠杆被迫去。<span class="marginnote">「隔夜回购」翻译成大白话：今天把债券「卖」给对方借钱，约好明天加一点利息「买」回来——本质是拿债券当抵押的隔夜借款。「折扣率」是抵押品要打的折：100 元的债券只借得到 95 元，那 5 元差价是安全垫；价格一跌，安全垫被要求加厚，人人都得多押或少借。</span>缺口不是再讲次贷产品条款，而是：<strong>没有保险的短批发债，在中心货币区里仍满足挤兑条件</strong>。Gorton：信息敏感的债在平静期当货币，压力期人人要查抵押品，流动性消失。</p><p>与东亚对照：那里是货币错配；这里主要是期限与抵押品错配，货币是美元自己。与金本位对照：那里是黄金约束；这里是私人安全资产供给的约束。</p><h3 id="影子银行不是「没牌照」的口号" tabindex="-1">影子银行不是「没牌照」的口号 <a class="header-anchor" href="#影子银行不是「没牌照」的口号" aria-label="Permalink to &quot;影子银行不是「没牌照」的口号&quot;">​</a></h3><p>监管边界外的期限转换才是定义。有牌照的银行也可以通过管道做同样的事；无牌照但期限匹配的基金不是影子银行核。把危机写成「 deregulation 四个字」，会漏掉安全资产需求、评级与批发市场的微观结构——后者仍不要写成交易手册。</p><p><span class="marginnote">Pozsar 把链条画成：贷款 → 证券化 → 管道 / 交易商 → MMF。挤兑发生在右端的短债。Adrian–Shin 把交易商杠杆与资产价格写成顺周期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层。(1) 安全资产：对无信息敏感债的需求，私人部门制造近似品。(2) 挤兑：折扣率与展期是攻击变量，类似储备流失。(3) 政策：担保商业票据、互换线、购入抵押品，等于把最后贷款人扩到影子链——大萧条课里没及时做的那一件。财政：银行资本空洞变成主权或有负债，接到欧债。乘数：ZLB 上财政空间打开，但金融加速器先把 \\(Y\\) 打穿。压力测试若只用历史折扣率，等于假设挤兑变量不变——与用默认 SE 当球形误差是同一类错误。</p><p><span class="marginnote">期限错配的直觉类比：像用「一晚一续」的短租开着一家十年才回本的餐厅——房东每天肯续租，生意照做；哪天房东们集体不续，餐厅就得当天贱卖厨具。回购挤兑就是房东们同一天敲门：资产没变坏，融资先断了。</span></p>',12)),(n(),A(B,null,{default:E(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASIA%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%A4%96%E5%9B%B4%E7%BE%8E%E5%85%83%E7%9F%AD%E5%80%BA%22%5D%20--%3E%20CORE%5B%22%E4%B8%AD%E5%BF%83%3A%20%E5%9B%9E%E8%B4%AD%E4%B8%8E%20ABCP%22%5D%0A%20%20CORE%20--%3E%20HAIR%5B%22%E6%8A%98%E6%89%A3%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HAIR%20--%3E%20DELEV%5B%22%E5%8E%BB%E6%9D%A0%E6%9D%86%E4%B8%8E%E7%81%AB%E7%BA%BF%E5%87%BA%E5%94%AE%22%5D%0A%20%20DELEV%20--%3E%20EZ%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%B8%BB%E6%9D%83-%E9%93%B6%E8%A1%8C%E5%9B%9E%E8%B7%AF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要用房价指数单独当因果：房价是抵押品，放大来自杠杆与短债。评级把优先档标成「类货币」，批发买方就不再做信用分析——信息敏感度被制度性压低，直到价格一动人人重新计算。这与东亚钉住把汇率风险藏进表是同族：平静期的廉价保险。折扣率才是挤兑的价格，不是房价本身。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是私人货币的脆弱承诺。存款保险把支票账户的挤兑关掉；回购在法律上是抵押借款，平静期当现金，没有对应的保险。抵押品价格与折扣率双动，净值加速器与流动性加速器一起。美联储扩表是对影子链做 Bagehot，互换线是对全球美元批发做 Bagehot——国际金融主干最后一课已经写过制度形式，本课给它历史对照。金本位下不能这么做；2008 能做，所以没有变成十年通缩，但公私边界被改写，最后一课独立性会回头看。会计上「表外」不改变挤兑：管道破产仍打回发起行的声誉与流动性线。",-1)),(n(),A(B,null,{default:E(()=>[i(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20MORT%5B%22%E6%8C%89%E6%8F%AD%E8%B4%B7%E6%AC%BE%22%5D%20--%3E%20SEC%5B%22%E8%AF%81%E5%88%B8%E5%8C%96%3A%20MBS%2FABS%22%5D%0A%20%20SEC%20--%3E%20PIPE%5B%22%E8%A1%A8%E5%A4%96%E7%AE%A1%E9%81%93%22%5D%0A%20%20SEC%20--%3E%20DEAL%5B%22%E4%BA%A4%E6%98%93%E5%95%86%E5%BA%93%E5%AD%98%22%5D%0A%20%20PIPE%20--%3E%20ABCP%5B%22ABCP%20%E7%9F%AD%E5%80%BA%E8%9E%8D%E8%B5%84%22%5D%0A%20%20DEAL%20--%3E%20REPO%5B%22%E9%9A%94%E5%A4%9C%E5%9B%9E%E8%B4%AD%E8%9E%8D%E8%B5%84%22%5D%0A%20%20ABCP%20--%3E%20MMF%5B%22%E8%B4%A7%E5%B8%81%E5%B8%82%E5%9C%BA%E5%9F%BA%E9%87%91%E6%8C%81%E6%9C%89%22%5D%0A%20%20REPO%20--%3E%20HAIR%7B%22%E6%8A%98%E6%89%A3%E7%8E%87%E4%B8%8A%E5%8D%87%22%7D%0A%20%20HAIR%20--%3E%20RUN%5B%22%E5%B1%95%E6%9C%9F%E5%81%9C%E6%AD%A2%20%E2%86%92%20%E7%81%AB%E7%BA%BF%E5%87%BA%E5%94%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">初学者容易把 2008 读成「房价跌所以银行亏了」。房价只是抵押品价格；真正的放大器是短债展期停止与折扣率跳升——同样幅度的房价下跌若落在无杠杆、期限匹配的持有人身上只是小幅缩水。看危机要盯融资端的价格（折扣率），不只盯资产端的价格（房价）。</span></p><p><span class="marginnote">Gorton 强调：危机是对债的挤兑，不是对股票的情绪。信息不敏感债变成信息敏感，是机制，不是标题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供如何交易 CDO 或回购的任何步骤，不重写量化栏定价。住房政策与社区再投资的政治争论不是机制核。下一课：欧元区把银行持有本国主权债，挤兑对象换成主权利差。后课默认：2008 用无保险批发挤兑 + 抵押品加速器读；与东亚同构在「短债」，不同构在「货币错配」。会计并表之后，影子链可以缩回有保险的银行，挤兑条件改变——这是监管改革的机制，不是牌照口号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子银行是无存款保险的期限转换，核在回购与 ABCP。</li><li>中心国家也可以突然停止，不必原罪。</li><li>折扣率与抵押品价格是挤兑变量，对应东亚的展期。</li><li>最后贷款人扩到影子链，避免金本位式十年通缩，但改写财政边界。</li><li>评级把优先档标成类货币，平静期关掉信用分析，压力期一起打开。</li><li>出处：Gorton 2010；Pozsar；Bernanke；Adrian and Shin。</li></ul>',6))])}const _=s(p,[["render",h]]);export{u as __pageData,_ as default};
